BEGIN;

-- 1. Cria o Schema (Obrigatório para usar o prefixo "sch_supervisorio.")
CREATE SCHEMA IF NOT EXISTS sch_supervisorio;

-- 2. Cria as tabelas dentro desse schema
CREATE TABLE IF NOT EXISTS sch_supervisorio.tb_parametro
(
    "idParametro" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "caminhoFotosClientes" character varying(600),
    "caminhoMapas" character varying(600),
    "caminhoVideoAProcessar" character varying(600),
    "caminhoVideoProcessados" character varying(600),
    gerarvideomarcacoes boolean DEFAULT false,
    "caminhoVideoMarcacoes" character varying(600) ,
    "intevalorFrames" integer DEFAULT 15,
    "escalaImagem" real DEFAULT 1,
    "modeloDeteccao" character varying(10) ,
    "toleranciaReconhecimento" real DEFAULT 0.6,
    padrao boolean NOT NULL DEFAULT false,
    nomeparametro character varying(100) ,
    finalizaraoidentificartodos boolean DEFAULT true,
    CONSTRAINT tb_parametro_pkey PRIMARY KEY ("idParametro")
);

CREATE TABLE IF NOT EXISTS sch_supervisorio.tb_cameras
(
    "idCamera" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "nomeCamera" character varying(20) COLLATE pg_catalog."default" NOT NULL,
    "andarCamera" integer,
    "nrsalaproximaCamera" integer,
    notaparaignorar real DEFAULT 0,
    notaidentificacao real,
    idlocalizacao bigint NOT NULL DEFAULT 1,
    CONSTRAINT tb_cameras_pkey PRIMARY KEY ("idCamera")
);

CREATE TABLE IF NOT EXISTS sch_supervisorio.tb_cenario
(
    idcenario integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    descricaocenario character varying(100) COLLATE pg_catalog."default" NOT NULL,
    ativo boolean NOT NULL DEFAULT true,
    padrao boolean NOT NULL DEFAULT false,
    idparametro bigint,
    CONSTRAINT tb_cenario_pkey PRIMARY KEY (idcenario),
    CONSTRAINT fk_parametro_cenario FOREIGN KEY (idparametro)
        REFERENCES sch_supervisorio.tb_parametro ("idParametro") MATCH SIMPLE
        ON UPDATE NO ACTION
        ON DELETE NO ACTION
        NOT VALID
);

CREATE TABLE IF NOT EXISTS sch_supervisorio.tb_cenariocamera
(
    idcenariocamera integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
      idcenario integer NOT NULL,
    idcamera integer,
    CONSTRAINT tb_cenariocamera_pkey PRIMARY KEY (idcenariocamera),
    CONSTRAINT fk_camera_cenariocamera FOREIGN KEY (idcamera)
        REFERENCES sch_supervisorio.tb_cameras ("idCamera") MATCH SIMPLE
        ON UPDATE NO ACTION
        ON DELETE NO ACTION
        NOT VALID,
    CONSTRAINT fk_cenario_cenariocamera FOREIGN KEY (idcenario)
        REFERENCES sch_supervisorio.tb_cenario (idcenario) MATCH SIMPLE
        ON UPDATE NO ACTION
        ON DELETE NO ACTION
        NOT VALID
);

CREATE TABLE IF NOT EXISTS sch_supervisorio.tb_evento
(
    idevento integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    nomeevento character varying(70) NOT NULL,
    eventoduracao integer,
    CONSTRAINT tb_evento_pkey PRIMARY KEY (idevento)
);

CREATE TABLE IF NOT EXISTS sch_supervisorio.tb_localizacao
(
    idlocalizacao bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    nomelocalizacao character varying(200) COLLATE pg_catalog."default" NOT NULL,
    mapacamera character varying(600) COLLATE pg_catalog."default",
    CONSTRAINT tb_localizacao_pkey PRIMARY KEY (idlocalizacao)
);


CREATE TABLE IF NOT EXISTS sch_supervisorio.tb_motor
(
    idmotor bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    nomemotor character varying(40) COLLATE pg_catalog."default",
    numversao real,
    nomefuncaochamada character varying(100) COLLATE pg_catalog."default",
    nomemetodo character varying(30) COLLATE pg_catalog."default",
    nomearquivojsonerno json,
    nomearquivoexterno character varying(500) COLLATE pg_catalog."default",
    ativo boolean DEFAULT true,
    padrao boolean DEFAULT false,
    notafacemascara real,
    CONSTRAINT tb_motor_pkey PRIMARY KEY (idmotor)
);



CREATE TABLE IF NOT EXISTS sch_supervisorio.tb_pessoa
(
    "idPessoa" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "documentoPessoa" character varying(20),
    "tipoPessoa" "char" DEFAULT 'C',
    "nomePessoa" character varying(100),
    "fotosPessoa" character varying(600),
    CONSTRAINT tb_pessoa_pkey PRIMARY KEY ("idPessoa")
);

CREATE TABLE IF NOT EXISTS sch_supervisorio.tb_pessoa_evento
(
    idpessoaevento bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    idpessoa bigint NOT NULL,
    idevento integer NOT NULL,
    eventocancelado boolean DEFAULT false,
    datahoraentrada timestamp without time zone,
    datahoraprevistasaida timestamp without time zone,
    datahoraefetivasaida timestamp without time zone,
    CONSTRAINT pkeventopessoa PRIMARY KEY (idpessoaevento),
    CONSTRAINT fkpessoa_evento_evento FOREIGN KEY (idevento)
        REFERENCES sch_supervisorio.tb_evento (idevento) MATCH SIMPLE
        ON UPDATE NO ACTION
        ON DELETE NO ACTION,
    CONSTRAINT fkpessoa_evento_pessoa FOREIGN KEY (idpessoa)
        REFERENCES sch_supervisorio.tb_pessoa ("idPessoa") MATCH SIMPLE
        ON UPDATE NO ACTION
        ON DELETE NO ACTION
);

CREATE TABLE IF NOT EXISTS sch_supervisorio.tb_reconhecimentos_detalhes
(
    idreconhecimento bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "idVideo" bigint,
    nomepastapessoa character varying(100),
    nomearquivofoto character varying(255),
    tempomarcacaosegundos real,
    notacomparacao real,
    notafaceland real,
    avaliacaofoto jsonb,
    avaliacaoframe jsonb,
    notafinal real,
    "notafacemascara " real,
    CONSTRAINT tb_reconhecimentos_detalhes_pkey PRIMARY KEY (idreconhecimento)
);

CREATE TABLE IF NOT EXISTS sch_supervisorio.tb_videos_processados
(
    "idVideo" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "nomeArquivoVideo" character varying(700) COLLATE pg_catalog."default",
    datahoraprocessamento timestamp without time zone,
    "nomeArquivoFoto" character varying(700) COLLATE pg_catalog."default",
    "tempoMarcacaoSegundos" real,
    "nomePastaPessoa" character varying COLLATE pg_catalog."default",
    "nomeCamera" character varying(20) COLLATE pg_catalog."default",
    idmotor bigint,
    "frameFrente" boolean,
    "fotoFrente" boolean,
    notacomparacao real,
    avaliacaofoto jsonb,
    avaliacaoframe jsonb,
    notafaceland real,
    notafinal real,
    notafacemascara real,
    identificada boolean DEFAULT false,
    nomearquivovideomarcacao character varying(700) COLLATE pg_catalog."default",
    segundomarcacao bigint,
    "idCamera" bigint,
    CONSTRAINT tb_videos_pkey PRIMARY KEY ("idVideo")
);


COMMIT;